#include "InputState.h"
namespace NeoEngine {bool InputState::Bind(std::string id,int32_t code){if(id.empty()||id.size()>64){m_Error=InputError::InvalidAction;return false;}for(const auto&a:m_Actions)if(a.id==id){m_Error=InputError::DuplicateAction;return false;}if(m_Actions.size()==kMaxActions){m_Error=InputError::Capacity;return false;}m_Actions.push_back({std::move(id),code,{}});m_Error=InputError::None;return true;}bool InputState::Rebind(const std::string&id,int32_t code){for(auto&a:m_Actions)if(a.id==id){a.code=code;a.state={};m_Error=InputError::None;return true;}m_Error=InputError::MissingAction;return false;}bool InputState::Push(int32_t code,bool pressed){if(m_Events.size()==kMaxEvents){m_Error=InputError::QueueFull;return false;}m_Events.push_back({code,pressed});m_Error=InputError::None;return true;}void InputState::BeginFrame(){for(auto&a:m_Actions)a.state.justPressed=a.state.justReleased=false;for(auto e:m_Events)for(auto&a:m_Actions)if(a.code==e.code){if(e.pressed&&!a.state.pressed)a.state.justPressed=true;if(!e.pressed&&a.state.pressed)a.state.justReleased=true;a.state.pressed=e.pressed;}m_Events.clear();}InputSnapshot InputState::Query(const std::string&id)const{for(const auto&a:m_Actions)if(a.id==id)return a.state;return {};}bool InputState::HasAction(const std::string&id)const{for(const auto&a:m_Actions)if(a.id==id)return true;return false;}}
